  `titel` varchar(150) NOT NULL COMMENT 'Kurztitel der Aufgabe',
  `beschreibung` text DEFAULT NULL COMMENT 'Detaillierte Beschreibung',
  `status` enum('offen','in_bearbeitung','fertig') NOT NULL COMMENT 'Status',
  `kategorie` enum('betrieb','unterweisung','berufsschule') NOT NULL COMMENT 'Kategorie',
